begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(17);
select set_config('test.equipment_layout', '{"body":{"x":0,"y":0,"z":0,"rotationX":0,"rotationY":0,"rotationZ":0,"scale":1},"objects":[{"id":"00000000-0000-4000-8000-000000000001","name":"Equipment","slug":"stool","x":0,"y":0,"z":0,"rotationX":0,"rotationY":0,"rotationZ":0,"scale":1,"attachment":"none","pulleyHeight":1.5}]}', true);
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.equipment_layout')::jsonb,'{objects,0,slug}',to_jsonb(slug))), slug || ' can be saved') from unnest(array['stool','plyo-box','resistance-band','row-machine','shoulder-press-machine']) slug;
select set_config('test.band_layout', jsonb_set(current_setting('test.equipment_layout')::jsonb,'{objects,0}',(current_setting('test.equipment_layout')::jsonb->'objects'->0) || '{"slug":"resistance-band","band":{"start":{"target":"left-hand","point":{"x":0,"y":0,"z":0}},"end":{"target":"right-foot","point":{"x":0,"y":0,"z":0}},"length":1.2}}'::jsonb)::text,true);
select ok(private.valid_studio_layout(current_setting('test.band_layout')::jsonb), 'band can follow a hand and foot');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.band_layout')::jsonb,'{objects,0,band,start,target}','"unknown"')), 'unknown band target rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.band_layout')::jsonb,'{objects,0,band,length}','7')), 'band span bounded');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.band_layout')::jsonb,'{objects,0,band,start,point,x}','11')), 'band offset bounded');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.band_layout')::jsonb,'{objects,0,band,start}','{"target":"equipment","objectId":"00000000-0000-4000-8000-000000000001","point":{"x":0,"y":0,"z":0}}')), 'band cannot attach to itself');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.band_layout')::jsonb,'{objects,0,slug}','"stool"')), 'band settings rejected on rigid props');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.band_layout')::jsonb,'{objects,0,band,start,objectId}','"00000000-0000-4000-8000-000000000001"')), 'body anchor cannot carry an equipment id');
select set_config('test.smith_layout', jsonb_set(current_setting('test.equipment_layout')::jsonb,'{objects,0}',(current_setting('test.equipment_layout')::jsonb->'objects'->0) || '{"slug":"smith-machine","machineRange":{"min":0.4,"max":2.8},"attachment":"both","machineUse":false}'::jsonb)::text,true);
select ok(private.valid_studio_layout(current_setting('test.smith_layout')::jsonb), 'Smith supports wide travel and free grips');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.smith_layout')::jsonb,'{objects,0,machineRange,min}','2.8')), 'reversed bar range rejected');
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.equipment_layout')::jsonb,'{objects,0}',(current_setting('test.equipment_layout')::jsonb->'objects'->0) || '{"slug":"shoulder-press-machine","machineUse":true,"machinePosition":0.5}'::jsonb)), 'shoulder press can drive its preset');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.equipment_layout')::jsonb,'{objects,0}',(current_setting('test.equipment_layout')::jsonb->'objects'->0) || '{"machineUse":true}'::jsonb)), 'rigid props cannot drive a machine preset');
select is((select count(*)::integer from public.equipment where slug in ('row-machine','shoulder-press-machine','stool','plyo-box','resistance-band')), 5, 'expanded taxonomy exists even before seed');
select * from finish();
rollback;
